// Utility
// ============================================================================
function _cc_setExclusive(group, checkedBox) {
    for (var i = 0; i < group.length; i++)
        if (group[i] !== checkedBox)
            group[i].checked = false;
    checkedBox.checked = true;
}
function _cc_ensureDir(dirPath) {
    if (!File.directoryExists(dirPath))
        File.createDirectory(dirPath);
}
function _cc_uniqueTempBase(viewId) {
    var t = new Date().getTime().toString();
    var safeId = String(viewId).replace(/[^\w\-\.]/g, "_");
    return _cc_normalizePathForExternal(scriptTempDir + pathSeparator + safeId + "_" + t);
}
function _cc_fileExistsSafe(p) {
    try {
        return p && p.length > 0 && File.exists(p);
    }
    catch (e) {
        return false;
    }
}
function _cc_waitForFileReady(filePath, timeoutMs, stableMs) {
    var t0 = new Date().getTime();
    var pollMs = 200;
    var seenOnce = false;
    var stableSince = -1;
    while (true) {
        var now = new Date().getTime();
        if ((now - t0) > timeoutMs)
            return false;
        if (File.exists(filePath)) {
            var canRead = false;
            try {
                var f = new File;
                f.openForReading(filePath);
                f.close();
                canRead = true;
            }
            catch (e) {
                canRead = false;
            }
            if (canRead) {
                if (!seenOnce) {
                    seenOnce = true;
                    stableSince = now;
                }
                else if ((now - stableSince) >= stableMs)
                    return true;
            }
            else {
                seenOnce = false;
                stableSince = -1;
            }
        }
        _cc_msleep(pollMs);
    }
}
function _cc_msleep(milliseconds) {
    var start = new Date().getTime();
    while (new Date().getTime() - start < milliseconds)
        processEvents();
}
function _cc_waitForFile(filePath, timeoutMs, settleMs) {
    var t0 = new Date().getTime();
    var pollMs = 250;
    while (!File.exists(filePath)) {
        if ((new Date().getTime() - t0) > timeoutMs)
            return false;
        _cc_msleep(pollMs);
    }
    if (settleMs > 0)
        _cc_msleep(settleMs);
    return true;
}
function _cc_deleteFileQuiet(path) {
    try {
        if (File.exists(path))
            File.remove(path);
    }
    catch (e) { }
}
var TAP_SASPRO_SETTINGS_KEY = "AstroTemps/SASproExecutable";
var TAP_SASPRO_LEGACY_SETTINGS_KEY = "FTAstro/SASproExecutable";
