function saveViewForSasproCLI(view) {
    var imgWindow = view.isMainView ? view.window : view.mainView.window;
    if (!imgWindow)
        throw new Error("Image window is undefined for the specified view.");
    _cc_ensureDir(scriptTempDir);
    var base = _cc_uniqueTempBase(imgWindow.mainView.id);
    var inputFilePath = base + "_in.fits";
    var outputFilePath = base + "_out.fits";
    var srcImg = imgWindow.mainView.image;
    var floatSample = srcImg.isReal;
    var isColor = (srcImg.colorSpace != ColorSpace_Gray);
    var tmp = new ImageWindow(srcImg.width, srcImg.height, srcImg.numberOfChannels, srcImg.bitsPerSample, floatSample, isColor, "SASpro_CC_Temp");
    tmp.mainView.beginProcess(UndoFlag_NoSwapFile);
    tmp.mainView.image.assign(srcImg);
    tmp.mainView.endProcess();
    if (!tmp.saveAs(inputFilePath, false, false, false, false)) {
        tmp.forceClose();
        throw new Error("Failed to save temporary FITS: " + inputFilePath);
    }
    tmp.forceClose();
    console.writeln("Saved temp input (clone): " + inputFilePath);
    return { inputFilePath: inputFilePath, outputFilePath: outputFilePath };
}
function TAP_ccResolveTargetView(target) {
    if (target == null)
        throw new Error("Cosmic Clarity target is null.");
    /*
     * The original standalone CosmicClarity_SASpro script calls its output
     * routines with an ImageWindow. AstroTemps orchestrates stages with a View.
     * ProcessInstance.executeOn() requires a View/Image object, so using
     * target.mainView on an already-valid View yields undefined.
     */
    try {
        if (target.image != null && typeof target.id == "string")
            return target; // PJSR View
    }
    catch (e0) { }
    try {
        if (target.mainView != null && !target.mainView.isNull)
            return target.mainView; // PJSR ImageWindow
    }
    catch (e1) { }
    throw new Error("Cosmic Clarity could not resolve the target as a PixInsight View or ImageWindow.");
}
function createDarkStarStarsOnlyImage(originalTarget, starlessWindow, starMode) {
    var originalView = TAP_ccResolveTargetView(originalTarget);
    var originalId = originalView.id;
    var starlessId = starlessWindow.mainView.id;
    var P = new PixelMath;
    P.expression = starMode == "additive"
        ? "(" + originalId + "-" + starlessId + ")"
        : "(" + originalId + "-" + starlessId + ")/(1-" + starlessId + ")";
    P.expression1 = "";
    P.expression2 = "";
    P.expression3 = "";
    P.useSingleExpression = true;
    P.symbols = "";
    P.clearImageCacheAndExit = false;
    P.cacheGeneratedImages = false;
    P.generateOutput = true;
    P.singleThreaded = false;
    P.optimization = true;
    P.use64BitWorkingImage = false;
    P.rescale = false;
    P.truncate = true;
    P.truncateLower = 0;
    P.truncateUpper = 1;
    P.createNewImage = true;
    P.showNewImage = true;
    P.newImageId = originalId + "_DarkStar_StarsOnly";
    P.newImageColorSpace = PixelMath.prototype.SameAsTarget;
    P.newImageSampleFormat = PixelMath.prototype.SameAsTarget;
    P.executeOn(originalView);
}
function processDarkStarOutput(outputFilePath, targetView) {
    var targetProcessView = TAP_ccResolveTargetView(targetView);
    if (!File.exists(outputFilePath))
        throw new Error("DarkStar output file not found: " + outputFilePath);
    _cc_msleep(3000);
    var opened = null, attempts = 4, retryDelayMs = 3000, lastError = "";
    for (var attempt = 1; attempt <= attempts; ++attempt) {
        try {
            console.noteln(format("Opening DarkStar output (attempt %d/%d): %s", attempt, attempts, outputFilePath));
            opened = ImageWindow.open(outputFilePath);
            if (opened && opened.length > 0)
                break;
            lastError = "ImageWindow.open() returned no windows.";
        }
        catch (e) {
            lastError = e.message;
        }
        if (attempt < attempts) {
            console.warningln(format("DarkStar output not ready yet, waiting %d ms before retry... (%s)", retryDelayMs, lastError));
            _cc_msleep(retryDelayMs);
        }
    }
    if (!opened || opened.length < 1)
        throw new Error("Failed to open DarkStar output image after multiple attempts: " + outputFilePath + "\nLast error: " + lastError);
    var outWindow = opened[0];
    outWindow.show();
    if (SetiAstroSharpParameters.darkStarShowStarsOnly)
        createDarkStarStarsOnlyImage(targetProcessView, outWindow, SetiAstroSharpParameters.darkStarMode || "unscreen");
    var pixelMath = new PixelMath;
    pixelMath.expression = outWindow.mainView.id;
    pixelMath.useSingleExpression = true;
    pixelMath.createNewImage = false;
    pixelMath.rescale = false;
    pixelMath.truncate = false;
    pixelMath.executeOn(targetProcessView);
    outWindow.forceClose();
    try {
        File.remove(outputFilePath);
        console.writeln("Deleted temp output: " + outputFilePath);
    }
    catch (e) {
        console.warningln("Could not delete temp output: " + e.message);
    }
}
function processOutputImage(outputFilePath, targetView) {
    var targetProcessView = TAP_ccResolveTargetView(targetView);
    if (!File.exists(outputFilePath))
        throw new Error("Cosmic Clarity output file not found: " + outputFilePath);
    _cc_msleep(3000);
    var opened = null, attempts = 4, retryDelayMs = 3000, lastError = "";
    for (var attempt = 1; attempt <= attempts; ++attempt) {
        try {
            console.noteln(format("Opening Cosmic Clarity output (attempt %d/%d): %s", attempt, attempts, outputFilePath));
            opened = ImageWindow.open(outputFilePath);
            if (opened && opened.length > 0)
                break;
            lastError = "ImageWindow.open() returned no windows.";
        }
        catch (e) {
            lastError = e.message;
        }
        if (attempt < attempts) {
            console.warningln(format("Output file not ready yet, waiting %d ms before retry... (%s)", retryDelayMs, lastError));
            _cc_msleep(retryDelayMs);
        }
    }
    if (!opened || opened.length < 1)
        throw new Error("Failed to open Cosmic Clarity output image after multiple attempts: " + outputFilePath + "\nLast error: " + lastError);
    var outWindow = opened[0];
    outWindow.show();
    console.writeln("Applying Cosmic Clarity output to target View: " + targetProcessView.id);
    var pixelMath = new PixelMath;
    pixelMath.expression = "iif(" + outWindow.mainView.id + " == 0, $T, " + outWindow.mainView.id + ")";
    pixelMath.useSingleExpression = true;
    pixelMath.createNewImage = false;
    pixelMath.executeOn(targetProcessView);
    outWindow.forceClose();
    try {
        File.remove(outputFilePath);
        console.writeln("Deleted temp output: " + outputFilePath);
    }
    catch (e) {
        console.warningln("Could not delete temp output: " + e.message);
    }
}
// ============================================================================
// CLI command building
// ============================================================================
function buildCosmicClarityArgs(inputFilePath, outputFilePath) {
    var args = [];
    inputFilePath = _cc_normalizePathForExternal(inputFilePath);
    outputFilePath = _cc_normalizePathForExternal(outputFilePath);
    var mode = SetiAstroSharpParameters.processMode || "sharpen";
    args.push(mode);
    args.push("-i");
    args.push(inputFilePath);
    args.push("-o");
    args.push(outputFilePath);
    if (SetiAstroSharpParameters.useGPU)
        args.push("--gpu");
    else
        args.push("--no-gpu");
    var scm = SetiAstroSharpParameters.stellarCorrectMode || "sharpen_only";
    if ((mode == "sharpen" || mode == "both") && scm != "sharpen_only") {
        args.push("--stellar-correct-mode");
        args.push(scm);
    }
    if (mode == "sharpen" || mode == "denoise" || mode == "both") {
        if (SetiAstroSharpParameters.tempStretch)
            args.push("--temp-stretch");
        else
            args.push("--no-temp-stretch");
        var tm = _cc_toFloat(SetiAstroSharpParameters.tempStretchTargetMedian, 0.25);
        if (tm < 0.01)
            tm = 0.01;
        if (tm > 0.50)
            tm = 0.50;
        args.push("--target-median");
        args.push(format("%.3f", tm));
    }
    var cs = _cc_toInt(SetiAstroSharpParameters.chunkSize, 256);
    var ov = _cc_toInt(SetiAstroSharpParameters.overlap, 64);
    if (cs < 64)
        cs = 64;
    if (cs > 2048)
        cs = 2048;
    if (ov < 0)
        ov = 0;
    if (ov >= cs)
        ov = Math.max(0, cs - 1);
    if (mode != "darkstar") {
        args.push("--chunk-size");
        args.push(format("%d", cs));
        args.push("--overlap");
        args.push(format("%d", ov));
    }
    if (mode == "sharpen" || mode == "both") {
        args.push("--sharpening-mode");
        args.push(SetiAstroSharpParameters.sharpeningMode || "Both");
        args.push("--stellar-amount");
        args.push(format("%.2f", SetiAstroSharpParameters.stellarAmount));
        args.push("--nonstellar-amount");
        args.push(format("%.2f", SetiAstroSharpParameters.nonStellarAmount));
        if (SetiAstroSharpParameters.autoPSF) {
            args.push("--auto-psf");
        }
        else {
            args.push("--no-auto-psf");
            args.push("--nonstellar-psf");
            args.push(format("%.2f", SetiAstroSharpParameters.nonStellarStrength));
        }
        if (SetiAstroSharpParameters.sharpenChannelsSeparately)
            args.push("--sharpen-channels-separately");
    }
    if (mode == "denoise" || mode == "both") {
        args.push("--denoise-luma");
        args.push(format("%.2f", SetiAstroSharpParameters.denoiseLuma));
        args.push("--denoise-color");
        args.push(format("%.2f", SetiAstroSharpParameters.denoiseColor));
        args.push("--denoise-mode");
        args.push(SetiAstroSharpParameters.denoiseMode || "full");
        if (SetiAstroSharpParameters.separateDenoiseChannels)
            args.push("--separate-channels");
        if (SetiAstroSharpParameters.denoiseModel == "Walking Noise")
            args.push("--denoise-walking");
        else if (SetiAstroSharpParameters.denoiseModel == "Lite (faster)")
            args.push("--denoise-lite");
    }
    if (mode == "superres") {
        args.push("--scale");
        args.push(format("%d", SetiAstroSharpParameters.superResScale || 2));
    }
    if (mode == "darkstar") {
        args.push("--star-removal-mode");
        args.push(SetiAstroSharpParameters.darkStarMode || "unscreen");
        args.push("--processing-path");
        args.push(SetiAstroSharpParameters.darkStarProcessingPath || "hybrid_luma_color");
        if (SetiAstroSharpParameters.darkStarShowStarsOnly)
            args.push("--show-extracted-stars");
        else
            args.push("--no-show-extracted-stars");
        args.push("--chunk-size");
        args.push(format("%d", _cc_toInt(SetiAstroSharpParameters.chunkSize, 512)));
        args.push("--overlap-frac");
        args.push(format("%.3f", _cc_toFloat(SetiAstroSharpParameters.darkStarOverlapFrac, 0.125)));
        args.push("--edge-padding");
        args.push(format("%d", _cc_toInt(SetiAstroSharpParameters.darkStarEdgePadding, 64)));
        if (SetiAstroSharpParameters.darkStarCompatibilityMode)
            args.push("--compatibility-mode");
        else
            args.push("--no-compatibility-mode");
    }
    if (mode == "satellite") {
        args.push("--mode");
        args.push(SetiAstroSharpParameters.satelliteMode || "full");
        if (SetiAstroSharpParameters.satelliteClipTrail)
            args.push("--clip-trail");
        else
            args.push("--no-clip-trail");
        args.push("--sensitivity");
        args.push(format("%.2f", SetiAstroSharpParameters.satelliteSensitivity));
    }
    return args;
}
function makeLauncher(program, prefixArgs, label) {
    return { program: program, prefixArgs: prefixArgs || [], label: label || String(program) };
}
function getDefaultPythonCmd() {
    return IS_WIN ? "python" : "python3";
}
function resolveSasproCliLauncher() {
    var mode = SetiAstroSharpParameters.cliLauncherMode;
    var launcherPath = (SetiAstroSharpParameters.cliLauncherPath || "").trim();
    var scriptPath = (SetiAstroSharpParameters.pythonScriptPath || "").trim();
    if (mode == "setiastrosuitepro cc (installed command)")
        return makeLauncher("setiastrosuitepro", ["cc"], "setiastrosuitepro cc (installed command)");
    if (mode == "Frozen setiastrosuitepro executable") {
        if (launcherPath.length == 0) {
            var def = getDefaultFrozenSasproPath();
            if (def.length > 0 && _cc_fileExistsSafe(def)) {
                launcherPath = def;
                SetiAstroSharpParameters.cliLauncherPath = launcherPath;
                SetiAstroSharpParameters.save();
            }
            else if (IS_LIN)
                throw new Error("Frozen executable mode selected, but no executable path is configured.\nOn Linux, please browse to your SetiAstroSuitePro executable.");
            else
                throw new Error("Frozen executable mode selected, but no executable path is configured.\nExpected default path:\n" + def);
        }
        return makeLauncher(launcherPath, ["cc"], "Frozen setiastrosuitepro executable");
    }
    if (mode == "python -m setiastro.saspro cc") {
        var py = launcherPath.length > 0 ? launcherPath : getDefaultPythonCmd();
        return makeLauncher(py, ["-m", "setiastro.saspro", "cc"], "python -m setiastro.saspro cc");
    }
    if (mode == "python setiastrosuitepro.py cc") {
        var py2 = launcherPath.length > 0 ? launcherPath : getDefaultPythonCmd();
        if (scriptPath.length == 0)
            throw new Error("python setiastrosuitepro.py mode selected, but no script path is configured.");
        return makeLauncher(py2, [scriptPath, "cc"], "python setiastrosuitepro.py cc");
    }
    // Auto-detect.
    // Prefer an executable explicitly resolved by AstroTemps before PATH aliases.
    var candidates = [];
    var savedExecutable = TAP_sasproSavedExecutable();
    if (savedExecutable.length > 0 && _cc_fileExistsSafe(savedExecutable))
        candidates.push(makeLauncher(savedExecutable, ["cc"], "Auto: saved SASpro executable"));
    var defaultFrozen = getDefaultFrozenSasproPath();
    if (defaultFrozen.length > 0 && _cc_fileExistsSafe(defaultFrozen))
        candidates.push(makeLauncher(defaultFrozen, ["cc"], "Auto: frozen default path"));
    if (launcherPath.length > 0 &&
        _cc_fileExistsSafe(launcherPath) &&
        launcherPath != savedExecutable &&
        launcherPath != defaultFrozen)
        candidates.push(makeLauncher(launcherPath, ["cc"], "Auto: configured frozen executable path"));
    if (IS_WIN) {
        try {
            var home = TAP_safeString(File.homeDirectory);
            var localCandidates = [
                home + "/AppData/Local/Programs/SetiAstroSuitePro/SetiAstroSuitePro.exe",
                home + "/AppData/Local/SetiAstroSuitePro/SetiAstroSuitePro.exe"
            ];
            for (var lc = 0; lc < localCandidates.length; ++lc)
                if (_cc_fileExistsSafe(localCandidates[lc]))
                    candidates.push(makeLauncher(localCandidates[lc], ["cc"], "Auto: local SASpro executable"));
        }
        catch (eLocal) { }
    }
    candidates.push(makeLauncher("setiastrosuitepro", ["cc"], "Auto: setiastrosuitepro cc"));
    if (IS_WIN) {
        candidates.push(makeLauncher("py", ["-3", "-m", "setiastro.saspro", "cc"], "Auto: py -3 -m setiastro.saspro cc"));
        candidates.push(makeLauncher("python", ["-m", "setiastro.saspro", "cc"], "Auto: python -m setiastro.saspro cc"));
    }
    else {
        candidates.push(makeLauncher("python3", ["-m", "setiastro.saspro", "cc"], "Auto: python3 -m setiastro.saspro cc"));
        candidates.push(makeLauncher("python", ["-m", "setiastro.saspro", "cc"], "Auto: python -m setiastro.saspro cc"));
    }
    if (scriptPath.length > 0) {
        var py3 = launcherPath.length > 0 ? launcherPath : getDefaultPythonCmd();
        candidates.push(makeLauncher(py3, [scriptPath, "cc"], "Auto: python setiastrosuitepro.py cc"));
    }
    return { isAuto: true, autoCandidates: candidates };
}
// ============================================================================
// External process execution
// ============================================================================
function runExternalProcessBlocking(program, args, options) {
    options = options || {};
    var process = new ExternalProcess;
    var started = false;
    var finished = false;
    var sawOnError = false;
    var errorCodes = [];
    var stderrText = "";
    var stdoutText = "";
    process.onStarted = function () {
        started = true;
        console.noteln("Started: " + program + " " + args.join(" "));
    };
    process.onStandardOutputDataAvailable = function () {
        var out = String(process.stdout);
        if (out && out.length > 0) {
            stdoutText += out;
            if (options.onStdOutText)
                options.onStdOutText(out);
        }
    };
    process.onStandardErrorDataAvailable = function () {
        var err = String(process.stderr);
        if (err && err.length > 0) {
            stderrText += err;
            if (options.onStdErrText)
                options.onStdErrText(err);
        }
    };
    process.onError = function (code) {
        sawOnError = true;
        errorCodes.push(code);
        console.warningln("Process onError event code: " + code + " (ignoring unless process never starts)");
    };
    process.onFinished = function () {
        finished = true;
        console.noteln("Process finished.");
    };
    var okStart = process.start(program, args);
    if (!okStart)
        return { ok: false, started: false, finished: false, stdout: stdoutText,
            stderr: (stderrText ? stderrText + "\n" : "") + "Failed to start process.",
            sawOnError: sawOnError, errorCodes: errorCodes };
    while (process.isStarting)
        processEvents();
    while (process.isRunning)
        processEvents();
    return { ok: started && finished, started: started, finished: finished,
        stdout: stdoutText, stderr: stderrText,
        sawOnError: sawOnError, errorCodes: errorCodes };
}
function createProgressTextHandler() {
    var lastPercent = -1;
    var lineBuffer = "";
    return {
        feedStdout: function (text) {
            lineBuffer += text;
            var lines = lineBuffer.split(/\r?\n/);
            if (lines.length > 0)
                lineBuffer = lines.pop();
            for (var i = 0; i < lines.length; i++) {
                var line = lines[i];
                if (!line || line.length === 0)
                    continue;
                var m = line.match(/PROGRESS:\s*(\d+)%/i);
                if (m) {
                    var p = parseInt(m[1], 10);
                    if (p !== lastPercent) {
                        lastPercent = p;
                        console.writeln(format("SASpro Cosmic Clarity Progress: %3d%%", p));
                    }
                }
                else {
                    console.writeln(line);
                }
            }
        },
        feedStderr: function (text) {
            var lines = String(text).split(/\r?\n/);
            for (var i = 0; i < lines.length; i++)
                if (lines[i] && lines[i].length > 0)
                    console.warningln(lines[i]);
        }
    };
}
function runSasproCliWithCandidate(candidate, ccArgs) {
    var handler = createProgressTextHandler();
    return runExternalProcessBlocking(candidate.program, candidate.prefixArgs.concat(ccArgs), { onStdOutText: function (t) { return handler.feedStdout(t); },
        onStdErrText: function (t) { return handler.feedStderr(t); } });
}
function TAP_sasproLauncherDiagnosticText(r) {
    var s = "";
    try {
        if (r && r.stderr)
            s += String(r.stderr);
        if (r && r.stdout) {
            if (s.length > 0)
                s += "\n";
            s += String(r.stdout);
        }
    }
    catch (e) { }
    if (s.length > 1200)
        s = s.substring(s.length - 1200);
    return s;
}
function TAP_sasproKnownLauncherFailure(r) {
    var s = TAP_sasproLauncherDiagnosticText(r).toLowerCase();
    return s.indexOf("python was not found") >= 0 ||
        s.indexOf("no module named") >= 0 ||
        s.indexOf("is not recognized as an internal or external command") >= 0 ||
        s.indexOf("cannot find the file") >= 0 ||
        s.indexOf("the system cannot find") >= 0 ||
        s.indexOf("command not found") >= 0;
}
function TAP_sasproCandidateProducedOutput(outputFilePath) {
    // runExternalProcessBlocking() returns only after the launcher exits. A valid
    // Cosmic Clarity CLI run must therefore have created the requested -o file.
    // Allow a short settling interval for filesystem flush/antivirus latency.
    return _cc_waitForFileReady(outputFilePath, 3500, 500);
}
function TAP_sasproRunCandidateAndValidate(candidate, ccArgs, outputFilePath) {
    // Always remove a stale output before probing a launcher, otherwise a failed
    // candidate could be mistaken for a successful one.
    _cc_deleteFileQuiet(outputFilePath);
    var r = runSasproCliWithCandidate(candidate, ccArgs);
    if (!r.started || !r.finished)
        return { ok: false, candidate: candidate, result: r,
            reason: "Launcher did not start/finish." };
    if (TAP_sasproCandidateProducedOutput(outputFilePath))
        return { ok: true, candidate: candidate, result: r };
    var diag = TAP_sasproLauncherDiagnosticText(r);
    var reason = TAP_sasproKnownLauncherFailure(r)
        ? "Launcher is unavailable or not configured."
        : "Process exited without producing the requested Cosmic Clarity output.";
    if (diag.length > 0)
        reason += "\n" + diag;
    return { ok: false, candidate: candidate, result: r, reason: reason };
}
function runSasproCli(launcherOrAuto, ccArgs, outputFilePath) {
    if (launcherOrAuto.isAuto) {
        var candidates = launcherOrAuto.autoCandidates;
        var failures = [];
        for (var i = 0; i < candidates.length; ++i) {
            var c = candidates[i];
            console.noteln("Trying launcher: " + c.label);
            var attempt = TAP_sasproRunCandidateAndValidate(c, ccArgs, outputFilePath);
            if (attempt.ok) {
                if ((c.program.indexOf("/") >= 0 ||
                    c.program.indexOf("\\") >= 0) &&
                    _cc_fileExistsSafe(c.program))
                    TAP_saveSASproExecutable(c.program);
                return {
                    ok: true,
                    launcher: c,
                    result: attempt.result
                };
            }
            console.warningln("Launcher did not produce output: " + c.label);
            failures.push(c.label + ": " + attempt.reason);
        }
        /*
         * Auto-detection is exhausted. Prompt once for the installed standalone
         * SASpro executable instead of entering a long wait on a false-positive
         * Python/App Execution Alias.
         */
        console.warningln("SASpro auto-detection did not find a working launcher. " +
            "Please select the SetiAstroSuitePro executable.");
        var chosen = TAP_promptForSASproExecutable();
        if (chosen.length > 0) {
            var manual = makeLauncher(chosen, ["cc"], "Selected SASpro executable");
            console.noteln("Trying launcher: " + manual.label);
            var manualAttempt = TAP_sasproRunCandidateAndValidate(manual, ccArgs, outputFilePath);
            if (manualAttempt.ok) {
                TAP_saveSASproExecutable(chosen);
                SetiAstroSharpParameters.cliLauncherPath = chosen;
                return {
                    ok: true,
                    launcher: manual,
                    result: manualAttempt.result
                };
            }
            failures.push(manual.label + ": " + manualAttempt.reason);
        }
        return {
            ok: false,
            error: failures.join("\n\n")
        };
    }
    var one = TAP_sasproRunCandidateAndValidate(launcherOrAuto, ccArgs, outputFilePath);
    if (one.ok)
        return {
            ok: true,
            launcher: launcherOrAuto,
            result: one.result
        };
    return {
        ok: false,
        error: one.reason
    };
}
function _cc_normalizePathForExternal(p) {
    if (!p)
        return p;
    var s = String(p);
    if (IS_WIN)
        s = s.split("/").join("\\");
    else
        s = s.split("\\").join("/");
    return s;
}
function TAP_findKnownSASproExecutable() {
    var saved = TAP_sasproSavedExecutable();
    if (saved.length > 0 && _cc_fileExistsSafe(saved))
        return saved;
    var def = getDefaultFrozenSasproPath();
    if (def.length > 0 && _cc_fileExistsSafe(def)) {
        TAP_saveSASproExecutable(def);
        return def;
    }
    try {
        var home = TAP_safeString(File.homeDirectory);
        var c = [
            home + "/AppData/Local/Programs/SetiAstroSuitePro/SetiAstroSuitePro.exe",
            home + "/AppData/Local/SetiAstroSuitePro/SetiAstroSuitePro.exe",
            "C:/Program Files/SetiAstroSuitePro/SetiAstroSuitePro.exe"
        ];
        for (var i = 0; i < c.length; ++i)
            if (_cc_fileExistsSafe(c[i])) {
                TAP_saveSASproExecutable(c[i]);
                return c[i];
            }
    }
    catch (e) { }
    return "";
}
function TAP_preflightSASproBackend() {
    var p = TAP_findKnownSASproExecutable();
    if (p.length > 0) {
        SetiAstroSharpParameters.cliLauncherPath = p;
        console.noteln("SASpro executable detected: " + p);
        return;
    }
    /*
     * A pip/module installation can still be discovered later by the launcher
     * probes, so don't force file selection. But make the dependency explicit
     * before the expensive image export.
     */
    var answer = (new MessageBox("<p><b>Cosmic Clarity - SASpro requires SetiAstroSuitePro to be installed and configured on this computer.</b></p>" +
        "<p>No standalone SASpro executable was detected in the known locations.</p>" +
        "<p>If SASpro is installed, choose <b>Yes</b> and select its executable now. " +
        "If you installed SASpro through Python/pip, choose <b>No</b> and AstroTemps " +
        "will continue with the command-line probes.</p>", "AstroTemps AutoProcessing Tool - SASpro", StdIcon_Information, StdButton_Yes, StdButton_No)).execute();
    if (answer == StdButton_Yes) {
        var chosen = "";
        try {
            Console.hide();
        }
        catch (e0) { }
        try {
            chosen = TAP_promptForSASproExecutable();
        }
        finally {
            try {
                Console.show();
            }
            catch (e1) { }
        }
        if (chosen.length == 0)
            throw new Error("SASpro executable selection was cancelled. " +
                "Choose the corresponding non-SASpro engine, or install/configure SetiAstroSuitePro.");
        SetiAstroSharpParameters.cliLauncherPath = chosen;
        TAP_saveSASproExecutable(chosen);
        console.noteln("SASpro executable selected: " + chosen);
    }
}
// ============================================================================
// Main CC execution
// ============================================================================
function runCosmicClarityViaSasproCLI(selectedView) {
    // Resolve the external dependency before exporting a large temporary FITS.
    TAP_preflightSASproBackend();
    var tempFiles = saveViewForSasproCLI(selectedView);
    var inputFilePath = tempFiles.inputFilePath;
    var outputFilePath = tempFiles.outputFilePath;
    var success = false;
    try {
        var inputTimeoutMs = Math.max(5000, _cc_toInt(SetiAstroSharpParameters.inputReadyTimeoutSec, 30) * 1000);
        var outputTimeoutMs = Math.max(10000, _cc_toInt(SetiAstroSharpParameters.outputReadyTimeoutSec, 300) * 1000);
        if (!_cc_waitForFileReady(inputFilePath, inputTimeoutMs, 1000))
            throw new Error("Temporary input file was not found/ready in time:\n" + inputFilePath);
        console.noteln("Input file ready: " + inputFilePath);
        // (deleted)
        var ccArgs = buildCosmicClarityArgs(inputFilePath, outputFilePath);
        var launcher = resolveSasproCliLauncher();
        var runResult = runSasproCli(launcher, ccArgs, outputFilePath);
        try {
            if (runResult && runResult.launcher && runResult.launcher.label)
                console.noteln("Launcher used: " + runResult.launcher.label);
        }
        catch (eTelemetry) { }
        if (!runResult || !runResult.ok) {
            var launcherError = runResult && runResult.error
                ? runResult.error
                : "No SASpro launcher completed successfully.";
            throw new Error("Cosmic Clarity - SASpro requires a working SetiAstroSuitePro backend.\n\n" +
                launcherError);
        }
        // Normally the validated launcher has already produced a stable output
        // file. Keep the long timeout only as a defensive fallback.
        if (!_cc_waitForFileReady(outputFilePath, outputTimeoutMs, 1500)) {
            var extra = "";
            try {
                if (runResult && runResult.result) {
                    var rr = runResult.result;
                    if (rr.stderr && rr.stderr.length > 0) {
                        var sErr = rr.stderr;
                        if (sErr.length > 2000)
                            sErr = sErr.substring(sErr.length - 2000);
                        extra += "\n\n--- CLI stderr (tail) ---\n" + sErr;
                    }
                    if (rr.stdout && rr.stdout.length > 0) {
                        var sOut = rr.stdout;
                        if (sOut.length > 2000)
                            sOut = sOut.substring(sOut.length - 2000);
                        extra += "\n\n--- CLI stdout (tail) ---\n" + sOut;
                    }
                }
                else if (runResult && runResult.error)
                    extra += "\n\n--- Launcher error ---\n" + runResult.error;
            }
            catch (eTail) { }
            throw new Error("SASpro CLI did not produce an output file in time:\n" + outputFilePath + extra);
        }
        if ((SetiAstroSharpParameters.processMode || "sharpen") == "darkstar")
            processDarkStarOutput(outputFilePath, selectedView);
        else
            processOutputImage(outputFilePath, selectedView);
        success = true;
    }
    finally {
        if (success) {
            _cc_deleteFileQuiet(inputFilePath);
            _cc_deleteFileQuiet(outputFilePath);
        }
        else {
            console.warningln("Keeping temp files for debugging:");
            console.warningln("  input:  " + inputFilePath);
            console.warningln("  output: " + outputFilePath);
        }
    }
}
