    // "SPCC transmission curve not found" or "NoFunction is not defined"
    // are real execution errors, not missing installed processes, and should
    // reach the user verbatim instead of being collapsed into a generic
    // "Script/Process X not found" dialog.
    var looksMissing = lower.indexOf("is not installed") >= 0 ||
        lower.indexOf("is not available to pjsr") >= 0 ||
        lower.indexOf("unable to locate") >= 0 ||
        lower.indexOf("no auto-detect launcher") >= 0 ||
        lower.indexOf("launcher failed") >= 0 ||
        lower.indexOf("cannot find") >= 0 ||
        lower.indexOf("script/process ") >= 0;
    if (!looksMissing)
        return "";
