    var tp = [];
    var i;
    for (i = 0; i < w.length; ++i)
        if (w[i].length > 0 && isFinite(Number(w[i])))
            wp.push(Number(w[i]));
    for (i = 0; i < t.length; ++i)
        if (t[i].length > 0 && isFinite(Number(t[i])))
            tp.push(Number(t[i]));
