    try {
        windows = ImageWindow.open(path);
    }
    finally {
        try {
            File.remove(path);
        }
        catch (eRemove) { }
    }
    if (windows == null || windows.length == 0 || windows[0] == null || windows[0].isNull)
        throw new Error("Unable to load the watermark's temporary image.");
