        gBlack.drawBitmap(x0, y0, scaledBmp);
        try {
            gBlack.end();
        }
        catch (eGB) { }
        var whiteBmp = new Bitmap(imgW, imgH);
        var gWhite = new Graphics(whiteBmp);
        gWhite.fillRect(0, 0, imgW, imgH, new Brush(0xffffffff));
        gWhite.drawBitmap(x0, y0, scaledBmp);
        try {
            gWhite.end();
        }
        catch (eGW) { }
        blackW = lighthouseWatermarkBitmapToWindow(blackBmp);
        whiteW = lighthouseWatermarkBitmapToWindow(whiteBmp);
        var blackId = blackW.mainView.id;
        var whiteId = whiteW.mainView.id;
        // The round-trip does NOT guarantee 3 channels: an all-grey canvas (white or
        // black TEXT on a black/white background - the common case) is written as a
        // GRAYSCALE png and read back as ONE channel, while coloured content comes
        // back as three. Asking for [1]/[2] on the grey case throws "Channel index
        // out of range" and silently leaves alpha at 0, i.e. no watermark at all.
        var blackCh = blackW.mainView.image.numberOfChannels;
        var whiteCh = whiteW.mainView.image.numberOfChannels;
        var chCount = (blackCh >= 3 && whiteCh >= 3) ? 3 : 1;
        alphaW = new ImageWindow(imgW, imgH, 1, 32, true, false, TAPLH_uniqueImageId("Lighthouse_WM_Alpha"));
        hideTemporaryWindow(alphaW);
        var PMa = new PixelMath;
        configurePixelMath(PMa);
        var diffTerms = [];
        for (var dc = 0; dc < chCount; ++dc)
            diffTerms.push("(" + lighthouseWatermarkChExpr(whiteId, whiteCh, dc) +
                "-" + lighthouseWatermarkChExpr(blackId, blackCh, dc) + ")");
        PMa.expression =
            "min(max(1 - (" + diffTerms.join(" + ") + ")/" + chCount + ", 0), 1)";
        quietExecuteOn(PMa, alphaW.mainView);
        var alphaId = alphaW.mainView.id;
        fgW = new ImageWindow(imgW, imgH, 3, 32, true, true, TAPLH_uniqueImageId("Lighthouse_WM_FG"));
        hideTemporaryWindow(fgW);
        var PMf = new PixelMath;
        configurePixelMath(PMf);
        PMf.useSingleExpression = false;
        var denomExpr = "max(" + alphaId + ", 1e-4)";
        PMf.expression = "min(max(" + lighthouseWatermarkChExpr(blackId, blackCh, 0) + "/" + denomExpr + ", 0), 1)";
        PMf.expression1 = "min(max(" + lighthouseWatermarkChExpr(blackId, blackCh, 1) + "/" + denomExpr + ", 0), 1)";
        PMf.expression2 = "min(max(" + lighthouseWatermarkChExpr(blackId, blackCh, 2) + "/" + denomExpr + ", 0), 1)";
        quietExecuteOn(PMf, fgW.mainView);
        var fgId = fgW.mainView.id;
        var opacityFrac = Math.range(isFinite(wm.opacity) ? wm.opacity / 100 : 0.8, 0, 1);
        var weightExpr = "((" + alphaId + ")*" + opacityFrac + ")";
