// ----------------------------------------------------------------------------
// UI
// ----------------------------------------------------------------------------
function lighthouseCreateCurvesControls(dialog) {
    var self = dialog;
    dialog.curveEditor = new LighthouseCurveEditor(dialog);
    dialog.curveEditor.toolTip = "<p><b>Point curve</b>, like Lightroom's. <b>Click</b> anywhere on the plot to add a point, then <b>drag</b> it. <b>Double-click</b> a point to remove it (the two end points stay). The live histogram is drawn behind the curve.</p><p>Up is brighter, right is the input value - so lifting the left half opens the shadows, and an S shape adds contrast.</p><p>Curves obey the <b>Luminosity Masks</b> and any <b>select area</b> regions, exactly like the other tools.</p>";
    dialog.curveEditor.setChannel(dialog.curveActiveChannel, dialog[LIGHTHOUSE_CURVE_CHANNELS[dialog.curveActiveChannel].prop]);
    // Dragging only repaints; the image re-renders once, on release.
    dialog.curveEditor.onCurveCommitted = function () {
        self.schedulePreview();
    };
    dialog.curveChannel_ComboBox = new ComboBox(dialog);
    for (var i = 0; i < LIGHTHOUSE_CURVE_CHANNELS.length; ++i)
        dialog.curveChannel_ComboBox.addItem(LIGHTHOUSE_CURVE_CHANNELS[i].label);
    dialog.curveChannel_ComboBox.currentItem = dialog.curveActiveChannel;
    dialog.attachComboNoWheel(dialog.curveChannel_ComboBox, function (index) {
        self.curveActiveChannel = Math.range(index, 0, LIGHTHOUSE_CURVE_CHANNELS.length - 1);
        self.curveEditor.setChannel(self.curveActiveChannel, self[LIGHTHOUSE_CURVE_CHANNELS[self.curveActiveChannel].prop]);
    }, function () { return self.curveActiveChannel; });
    dialog.curveChannel_Sizer = dialog.optionRow("Channel", dialog.curveChannel_ComboBox);
    dialog.curveReset_Button = new PushButton(dialog);
    dialog.curveReset_Button.text = "Reset channel";
    dialog.curveReset_Button.backgroundColor = UI_PANEL;
    dialog.curveReset_Button.foregroundColor = UI_TEXT;
    dialog.curveReset_Button.defaultButton = false;
    dialog.curveReset_Button.toolTip = "<p>Straighten the curve for the channel shown above, back to the neutral diagonal.</p>";
    dialog.curveReset_Button.onClick = function () {
        self.curveEditor.resetCurve();
    };
    dialog.curveResetAll_Button = new PushButton(dialog);
    dialog.curveResetAll_Button.text = "Reset all";
    dialog.curveResetAll_Button.backgroundColor = UI_PANEL;
    dialog.curveResetAll_Button.foregroundColor = UI_TEXT;
    dialog.curveResetAll_Button.defaultButton = false;
    dialog.curveResetAll_Button.toolTip = "<p>Straighten all four curves - RGB, Red, Green and Blue.</p>";
    dialog.curveResetAll_Button.onClick = function () {
        for (var k = 0; k < LIGHTHOUSE_CURVE_CHANNELS.length; ++k) {
            var arr = self[LIGHTHOUSE_CURVE_CHANNELS[k].prop];
            arr.length = 0;
            arr.push({ x: 0, y: 0 });
            arr.push({ x: 1, y: 1 });
        }
        self.curveEditor.setChannel(self.curveActiveChannel, self[LIGHTHOUSE_CURVE_CHANNELS[self.curveActiveChannel].prop]);
        self.schedulePreview();
    };
    dialog.curveButtons_Sizer = new HorizontalSizer;
    dialog.curveButtons_Sizer.spacing = 6;
    dialog.curveButtons_Sizer.add(dialog.curveReset_Button);
    dialog.curveButtons_Sizer.add(dialog.curveResetAll_Button);
    dialog.curveButtons_Sizer.addStretch();
    dialog.updateCurvesControlsEnabled = function (enabled) {
        var on = (enabled !== false);
        self.curveEditor.enabled = on;
        self.curveChannel_ComboBox.enabled = on;
        self.curveReset_Button.enabled = on;
        self.curveResetAll_Button.enabled = on;
        if (self.curveChannel_ComboBox.rowLabel != null) {
            self.curveChannel_ComboBox.rowLabel.enabled = on;
            self.curveChannel_ComboBox.rowLabel.foregroundColor = on ? UI_TEXT : UI_TEXT_DISABLED;
        }
    };
    dialog.resetCurvesValues = function () {
        lighthouseCurvesInitDefaults(self);
        self.curveChannel_ComboBox.currentItem = self.curveActiveChannel;
        self.curveEditor.setChannel(self.curveActiveChannel, self[LIGHTHOUSE_CURVE_CHANNELS[self.curveActiveChannel].prop]);
        self.updateCurvesControlsEnabled(self.processingControlsEnabled !== false);
    };
}
function lighthouseAssembleCurvesGroup(dialog) {
    dialog.curvesGroup = new LighthouseCategoryFrame(dialog, "Curves");
    dialog.curvesGroup.contentSizer.margin = 8;
    dialog.curvesGroup.contentSizer.spacing = 4;
    dialog.curvesGroup.contentSizer.add(dialog.curveChannel_Sizer);
    dialog.curvesGroup.contentSizer.addSpacing(2);
    dialog.curvesGroup.contentSizer.add(dialog.curveEditor);
    dialog.curvesGroup.contentSizer.addSpacing(4);
    dialog.curvesGroup.contentSizer.add(dialog.curveButtons_Sizer);
}
/* ---- LighthouseHSL.jsh ---- */
///////////////////////////////////////////////////////////////////////////////
// LighthouseHSL.jsh - Lightroom-style HSL / Color Mixer for Lighthouse.
//
// Included ONLY by Lighthouse_v97_preview.js. Eight colour bands
// (Red / Orange / Yellow / Green / Aqua / Blue / Purple / Magenta), each with
// Hue, Saturation and Luminance, exactly like Lightroom's Color Mixer. The pass
// runs on the recombined RGB inside Engine.execute, straight after Selective
// Color, and is gated by the standard mask/region weight - so luminosity masks,
// regions and Invert apply to it like every other tool.
//
// Panel layout follows Lightroom: a Channel selector (Hue / Saturation /
// Luminance) with all eight colour sliders shown at once underneath, rather than
// one colour at a time. The eight slider grooves repaint themselves for the
// selected channel, so each one always shows what its two directions do.
//
// CLASSIFICATION is shared with Selective Color: the same OKLab cosine-similarity
// membership, the same chroma weighting, the same shadow guard and the same mask
// smoothing (lighthouseSelColorMembershipExpression et al). Both files ship
// together, so this reuse is deliberate - it guarantees the two tools agree about
// what "Blues" means, and any future improvement to the classifier benefits both.
//
// The SELECTION TUNING is shared too, and there is deliberately no second set of
// Range / Protect shadows / Smoothness sliders here: this panel reads Selective
// Color's per-group values (lighthouseHSLTuningFor). What counts as "blue" is
// described in exactly one place and both tools obey it.
//
// THE CORRECTION ITSELF is done in OKLab, which is what makes it behave like
// Lightroom rather than like a channel mixer:
//   Hue        - rotates the (a,b) chroma vector, so the colour changes without
//                touching brightness or how saturated it looks.
//   Saturation - scales the length of that vector. A neutral pixel has length 0,
//                so it stays neutral no matter how far the slider is pushed.
//   Luminance  - scales OKLab L, which is perceptual lightness, so the hue and
//                saturation survive the brightness change.
// The band half-widths below were derived the same way as Selective Color's (mean
// angular distance to each band's two neighbours x1.15) and verified to cover the
// hue circle with no gaps: minimum membership sum ~0.993.
///////////////////////////////////////////////////////////////////////////////
// key, label, OKLab hue direction (ua,ub), cos(half width), swatch chip.
// The directions are the OKLab chroma angles of the fully saturated sRGB colours
// at the HSV hues Lightroom uses for its eight bands.
var LIGHTHOUSE_HSL_BANDS = [
    { key: "Reds", label: "Red", ua: 0.872633, ub: 0.488376, cosHW: 0.500516, swatch: 0xffd85a4c },
    { key: "Oranges", label: "Orange", ua: 0.133649, ub: 0.991029, cosHW: 0.690784, swatch: 0xffd8874c },
    { key: "Yellows", label: "Yellow", ua: -0.338233, ub: 0.941063, cosHW: 0.823125, swatch: 0xffd8bd42 },
    { key: "Greens", label: "Green", ua: -0.793304, ub: 0.608826, cosHW: 0.657706, swatch: 0xff42a85f },
    { key: "Aquas", label: "Aqua", ua: -0.966962, ub: -0.254922, cosHW: 0.343740, swatch: 0xff42c0d8 },
    { key: "Blues", label: "Blue", ua: -0.103625, ub: -0.994616, cosHW: 0.294517, swatch: 0xff4c78d8 },
    { key: "Purples", label: "Purple", ua: 0.782629, ub: -0.622489, cosHW: 0.736829, swatch: 0xff8a5ccf },
    { key: "Magentas", label: "Magenta", ua: 0.927387, ub: -0.374103, cosHW: 0.777740, swatch: 0xffcf5ca0 }
];
// Channel = which of the three values the eight sliders are editing.
var LIGHTHOUSE_HSL_CHANNELS = [
    { suffix: "Hue", label: "Hue" },
    { suffix: "Sat", label: "Saturation" },
    { suffix: "Lum", label: "Luminance" }
];
// Which Selective Color group(s) supply each band's selection tuning. Five of the
// eight bands share a hue direction with a Selective Color group exactly (Red,
// Yellow, Green, Aqua = Cyans, Blue), so they simply read that group. Orange and
// Purple sit between two groups and average them; Magenta is nearest Magentas.
// Editing Range / Protect shadows / Smoothness in the Selective Color box
// therefore retunes the matching colour here too - that is the point.
var LIGHTHOUSE_HSL_SC_SOURCE = [
    [0], // Red     <- Reds
    [0, 1], // Orange  <- between Reds and Yellows
    [1], // Yellow  <- Yellows
    [2], // Green   <- Greens
    [3], // Aqua    <- Cyans (same hue direction)
    [4], // Blue    <- Blues
    [4, 5], // Purple  <- between Blues and Magentas
    [5] // Magenta <- Magentas
];
