    var A = lighthouseHSLAxisValue(aId);
    var B = lighthouseHSLAxisValue(bId);
    var lp = "(" + L + " + 0.3963377774*" + A + " + 0.2158037573*" + B + ")";
    var mp = "(" + L + " - 0.1055613458*" + A + " - 0.0638541728*" + B + ")";
    var sp = "(" + L + " - 0.0894841775*" + A + " - 1.2914855480*" + B + ")";
