    configurePixelMath(PM_guard);
    PM_guard.expression =
        "(min(max((max($T - " + BlurW.mainView.id + ", 0) - 0.010)/0.045, 0), 1))^0.35";
    quietExecuteOn(PM_guard, W.mainView);
    convolveView(W.mainView, 3.5 * pxScale);
