    this.selectionEditHandle = null; // which handle is being dragged: center/left/right/top/bottom
    this.selEditOrig = null; // active-region snapshot at grab time (center move / rotate)
    // Watermark placement (LighthouseWatermark.jsh). Mirrored from the dialog's
    // watermark* fields (this control has no back-reference to the dialog, same
    // convention as selectionRegions above) - see lighthouseWatermarkRefreshPreviewMirror.
    this.watermarkEnabled = false;
    this.watermarkRegion = null; // {cx,cy,w,h} normalized, full-image coords
