    this.iconBar_Sizer.add(this.documentation_Button);
    this.leftPanel.sizer.add(this.iconBar_Sizer);
    this.leftPanel.setScaledFixedWidth(controlLabelWidth + controlEditWidth + controlSliderWidth + 40);
    this.lockPanelHeight(this.leftPanel);
    this.categoryFrames = [
        this.whiteBalanceGroup,
        this.lrGroup,
        this.additionalGroup,
        this.curvesGroup,
        this.luminosityMaskGroup,
        this.noiseReductionGroup,
        this.waveletGroup,
        this.selColorGroupFrame,
        this.hslGroup,
        this.watermarkGroup
    ];
    this.leftPanelStaticHeight = this.leftPanel.height;
    for (var cf = 0; cf < this.categoryFrames.length; ++cf)
        this.leftPanelStaticHeight -= this.categoryFrames[cf].currentFrameHeight();
    this.updateLeftPanelCollapsedHeight = function () {
        var h = self.leftPanelStaticHeight;
        for (var i = 0; i < self.categoryFrames.length; ++i)
            h += self.categoryFrames[i].currentFrameHeight();
        self.leftPanel.setFixedHeight(Math.max(1, h));
        if (self.updateLeftPanelScroll)
            self.updateLeftPanelScroll();
    };
    // Accordion mode: opening one tool box closes the others, so the panel stays
    // short and every option is reachable without scrolling past several open boxes.
    this.accordionBusy = false; // guard: setCollapsed() re-enters this handler
    this.applyAccordion = function (openedFrame) {
        if (!self.accordionMode || self.accordionBusy)
            return;
        // Only react to a box being OPENED - collapsing one should not reopen anything.
        if (openedFrame == null || openedFrame.collapsed)
            return;
        self.accordionBusy = true;
        try {
            for (var i = 0; i < self.categoryFrames.length; ++i) {
                var f = self.categoryFrames[i];
                if (f !== openedFrame && !f.collapsed)
                    f.setCollapsed(true);
            }
        }
        catch (e) {
        }
        finally {
            self.accordionBusy = false;
        }
        self.updateLeftPanelCollapsedHeight();
        self.scrollCategoryIntoView(openedFrame);
    };
    // Bring a just-opened box to the top of the scrolled area, so its controls are
    // visible immediately instead of below the viewport.
    this.scrollCategoryIntoView = function (frame) {
        if (frame == null || self.leftPanel_ScrollBox == null)
            return;
        try {
            if (self.updateLeftPanelScroll)
                self.updateLeftPanelScroll();
            var y = frame.position.y - 6;
            self.leftPanel_ScrollBox.verticalScrollPosition = Math.range(y, 0, Math.max(0, self.leftPanel_ScrollBox.maxVerticalScrollPosition));
        }
        catch (e) {
        }
    };
    for (var cfi = 0; cfi < this.categoryFrames.length; ++cfi) {
        this.categoryFrames[cfi].onCollapseChanged = function (frame) {
            self.updateLeftPanelCollapsedHeight();
            self.applyAccordion(frame);
        };
    }
    this.additionalGroup.setCollapsed(true);
    this.luminosityMaskGroup.setCollapsed(true);
    this.noiseReductionGroup.setCollapsed(true);
    this.waveletGroup.setCollapsed(true);
    this.selColorGroupFrame.setCollapsed(true);
    this.hslGroup.setCollapsed(true);
    // Honour a restored "one box at a time" preference straight away (the default
    // layout leaves two boxes open).
    if (this.accordionMode) {
        for (var acf = 0; acf < this.categoryFrames.length; ++acf)
            if (!this.categoryFrames[acf].collapsed) {
                this.applyAccordion(this.categoryFrames[acf]);
                break;
            }
    }
    this.updateLeftPanelScroll = function () {
        var maxScroll = Math.max(0, self.leftPanel.height - self.leftPanel_ScrollBox.viewport.height);
        self.leftPanel_ScrollBox.maxVerticalScrollPosition = maxScroll;
        self.leftPanel_ScrollBox.maxHorizontalScrollPosition = 0;
        self.leftPanel_ScrollBox.verticalScrollPosition = Math.range(self.leftPanel_ScrollBox.verticalScrollPosition, 0, maxScroll);
        self.leftPanel.move(0, -self.leftPanel_ScrollBox.verticalScrollPosition);
        self.leftPanel_ScrollBox.viewport.update();
    };
    this.leftPanel_ScrollBox.onVerticalScrollPosUpdated = function (newPos) {
        self.leftPanel.move(0, -newPos);
        this.viewport.update();
    };
    this.leftPanel_ScrollBox.viewport.onResize = function (wNew, hNew, wOld, hOld) {
        self.updateLeftPanelScroll();
    };
    this.attachToolWheel(this.leftPanel_ScrollBox);
    this.attachToolWheel(this.leftPanel_ScrollBox.viewport);
