    this.attachToolWheel(this.clarityRadiusFold);
    this.attachToolWheel(this.additionalGroup);
    this.attachToolWheel(this.luminosityMaskGroup);
    this.attachToolWheel(this.noiseReductionGroup);
    this.attachToolWheel(this.midtoneLow_CheckBox);
