    this.attachToolWheel(this.midtoneHigh_CheckBox);
    this.attachToolWheel(this.scnrInverse_CheckBox);
    this.attachToolWheel(this.lumMaskEnabled_CheckBox);
    // (lumMask Type/Depth/Mode combos use attachComboNoWheel - do NOT attachToolWheel
    //  them here or it would overwrite the wheel guard.)
    this.attachToolWheel(this.lumMaskShow_CheckBox);
    this.attachToolWheel(this.lumMaskShowGray_CheckBox);
