    this.version_Label.textAlignment = TextAlign_Center;
    // -----------------------------------------------------------------
    // Settings
    // -----------------------------------------------------------------
    this.target_Group = new GroupBox(this);
    this.target_Group.title = "Settings";
    this.target_Label = new Label(this.target_Group);
    this.target_Label.text = "Image:";
    this.target_Label.textAlignment = TextAlign_Right | TextAlign_VertCenter;
    this.target_ViewList = new ViewList(this.target_Group);
    this.target_ViewList.getMainViews();
    if (!ImageWindow.activeWindow.isNull)
        this.target_ViewList.currentView = ImageWindow.activeWindow.mainView;
    this.copy_CheckBox = new CheckBox(this.target_Group);
    this.copy_CheckBox.text = "Create Working Copy before processing";
    this.copy_CheckBox.checked = initialSettings.createCopy;
    this.backupEachProcess_CheckBox = new CheckBox(this.target_Group);
    this.backupEachProcess_CheckBox.text = "Create a copy of the file after every process";
    this.backupEachProcess_CheckBox.checked = initialSettings.backupEachProcess;
    this.backupEachProcess_CheckBox.toolTip =
        "<p>Creates in-memory PixInsight image snapshots after the supported processing stages. " +
            "The workflow itself always continues on the same <b>_work</b> target.</p>";
    this.stf_CheckBox = new CheckBox(this.target_Group);
    this.stf_CheckBox.text = "Apply Auto STF after relevant steps";
    this.stf_CheckBox.checked = initialSettings.autoSTF;
    this.stf_CheckBox.toolTip =
        "<p>Visualization only. RGB Unlinked before SPCC and RGB Linked after SPCC.</p>";
    this.customOrder_CheckBox = new CheckBox(this.target_Group);
    this.customOrder_CheckBox.text = "Customize process execution order";
    this.customOrder_CheckBox.checked = initialSettings.customizeOrder;
    this.customOrder_CheckBox.toolTip =
        "<p>Select a process below and move it up or down. " +
            "The accordion panels remain in their normal visual order, while execution follows this custom sequence.</p>";
    this.executionOrder = TAP_normalizeExecutionOrder(initialSettings.executionOrder);
    this.order_Control = new Control(this.target_Group);
    this.order_Select_Label = new Label(this.order_Control);
    this.order_Select_Label.text = "Move process:";
    this.order_Select_Label.textAlignment = TextAlign_Right | TextAlign_VertCenter;
    this.order_Combo = new ComboBox(this.order_Control);
    this.orderUp_Button = new PushButton(this.order_Control);
    this.orderUp_Button.text = "▲";
    this.orderUp_Button.toolTip = "Move the selected process one position earlier.";
    this.orderDown_Button = new PushButton(this.order_Control);
    this.orderDown_Button.text = "▼";
    this.orderDown_Button.toolTip = "Move the selected process one position later.";
    this.orderPreview_Label = new Label(this.order_Control);
    this.orderPreview_Label.wordWrapping = true;
    this.orderPreview_Label.useRichText = true;
    var orderRow = new HorizontalSizer;
    orderRow.spacing = 6;
    orderRow.add(this.order_Select_Label);
    orderRow.add(this.order_Combo, 100);
    orderRow.add(this.orderUp_Button);
    orderRow.add(this.orderDown_Button);
    this.order_Control.sizer = new VerticalSizer;
    this.order_Control.sizer.margin = 0;
    this.order_Control.sizer.spacing = 4;
    this.order_Control.sizer.add(orderRow);
    this.order_Control.sizer.add(this.orderPreview_Label);
    this.refreshOrderControls = function (selectedIndex) {
        dialog.executionOrder = TAP_normalizeExecutionOrder(dialog.executionOrder);
        dialog.order_Combo.clear();
        for (var i = 0; i < dialog.executionOrder.length; ++i)
            dialog.order_Combo.addItem(TAP_STAGE_LABELS[dialog.executionOrder[i]]);
        if (selectedIndex == null)
            selectedIndex = 0;
        selectedIndex = Math.max(0, Math.min(dialog.executionOrder.length - 1, selectedIndex));
        dialog.order_Combo.currentItem = selectedIndex;
        dialog.orderPreview_Label.text =
            "<i>Execution: " + TAP_executionOrderText(dialog.executionOrder) + "</i>";
        dialog.orderUp_Button.enabled =
            dialog.customOrder_CheckBox.checked && selectedIndex > 0;
        dialog.orderDown_Button.enabled =
            dialog.customOrder_CheckBox.checked && selectedIndex < dialog.executionOrder.length - 1;
    };
    this.order_Combo.onItemSelected = function (index) {
        dialog.refreshOrderControls(index);
    };
    this.orderUp_Button.onClick = function () {
        var i = dialog.order_Combo.currentItem;
        if (i <= 0)
            return;
        var tmp = dialog.executionOrder[i - 1];
        dialog.executionOrder[i - 1] = dialog.executionOrder[i];
        dialog.executionOrder[i] = tmp;
        dialog.refreshOrderControls(i - 1);
    };
    this.orderDown_Button.onClick = function () {
        var i = dialog.order_Combo.currentItem;
        if (i < 0 || i >= dialog.executionOrder.length - 1)
            return;
        var tmp = dialog.executionOrder[i + 1];
        dialog.executionOrder[i + 1] = dialog.executionOrder[i];
        dialog.executionOrder[i] = tmp;
        dialog.refreshOrderControls(i + 1);
    };
    this.customOrder_CheckBox.onCheck = function (checked) {
        dialog.order_Control.visible = checked;
        dialog.refreshOrderControls(dialog.order_Combo.currentItem);
        dialog.adjustToContents();
    };
    var targetRow = new HorizontalSizer;
    targetRow.spacing = 6;
    targetRow.add(this.target_Label);
    targetRow.add(this.target_ViewList, 100);
    this.target_Group.sizer = new VerticalSizer;
    this.target_Group.sizer.margin = 8;
    this.target_Group.sizer.spacing = 6;
    this.target_Group.sizer.add(targetRow);
    this.target_Group.sizer.add(this.copy_CheckBox);
    this.target_Group.sizer.add(this.backupEachProcess_CheckBox);
    this.target_Group.sizer.add(this.stf_CheckBox);
    this.target_Group.sizer.add(this.customOrder_CheckBox);
    this.target_Group.sizer.add(this.order_Control);
    this.refreshOrderControls(0);
    this.order_Control.visible = this.customOrder_CheckBox.checked;
    // -----------------------------------------------------------------
    // Accordion helpers
    // -----------------------------------------------------------------
    this.sections = [];
    this._layoutBusy = false;
    this.compactReflow = function () {
        if (dialog._layoutBusy)
            return;
        dialog._layoutBusy = true;
        try {
            // Do not freeze section heights. Hidden bodies must be allowed to
            // collapse to zero naturally; fixed heights were the source of the
            // residual spacing seen after repeated expand/collapse operations.
            dialog.setVariableHeight();
            for (var i = 0; i < dialog.sections.length; ++i) {
                var sec = dialog.sections[i];
                try {
                    sec.control.setVariableHeight();
                }
                catch (e0) { }
                try {
                    sec.headerControl.setVariableHeight();
                }
                catch (e1) { }
                try {
                    sec.body.setVariableHeight();
                }
                catch (e2) { }
                sec.body.visible = !!sec.expanded;
            }
            // First pass resolves all visibility changes.
            processEvents();
            for (var j = 0; j < dialog.sections.length; ++j) {
                var s = dialog.sections[j];
                try {
                    if (s.expanded)
                        s.body.adjustToContents();
                    s.headerControl.adjustToContents();
                    s.control.adjustToContents();
                }
                catch (e3) { }
            }
            dialog.adjustToContents();
            // A second event/layout pass avoids the one-frame stale geometry that
            // some Windows/PJSR controls report immediately after show/hide.
            processEvents();
            dialog.adjustToContents();
        }
        finally {
            dialog._layoutBusy = false;
        }
    };
    this.registerSection = function (section) {
        dialog.sections.push(section);
        section.onToggle = function (expanded) {
            if (expanded) {
                // Accordion behavior: one processing stage open at a time.
                // Suppress intermediate reflows and perform one compact layout pass
                // after all other bodies have been hidden.
                for (var i = 0; i < dialog.sections.length; ++i)
                    if (dialog.sections[i] !== section)
                        dialog.sections[i].setExpanded(false, false);
            }
            dialog.compactReflow();
        };
        return section;
    };
    // -----------------------------------------------------------------
    // 1. Optical Correction
    // -----------------------------------------------------------------
    this.preprocess_Section = this.registerSection(new TAP_CollapsibleSection(this, "1. Optical Correction", true, initialSettings.blurCorrect));
    var p1 = this.preprocess_Section.body;
    this.blurCorrect_CheckBox = new CheckBox(p1);
    this.blurCorrect_CheckBox.text = "Run Optical Correction";
    this.blurCorrect_CheckBox.checked = initialSettings.blurCorrect;
    this.opticalEngine_Label = new Label(p1);
    this.opticalEngine_Label.text = "Engine:";
    this.opticalEngine_Label.textAlignment = TextAlign_Right | TextAlign_VertCenter;
    this.opticalEngine_Combo = new ComboBox(p1);
