    this.spccFilterNames = TAP_loadSPCCFilterNames();
    function makeFilterCombo(parent, labelText, initialValue, channel) {
        var row = new HorizontalSizer;
        row.spacing = 6;
        var label = new Label(parent);
        label.text = labelText;
        label.textAlignment = TextAlign_Right | TextAlign_VertCenter;
        var combo = new ComboBox(parent);
        var channelNames = TAP_spccFilterNamesForChannel(dialog.spccFilterNames, channel);
        for (var i = 0; i < channelNames.length; ++i)
            combo.addItem(channelNames[i]);
        // If an old saved setting points to a channel-specific filter from the
        // wrong channel, do not reinsert it. Fall back to the native SPCC sensor
        // default for this channel instead.
        var selected = initialValue;
        var selectedChannel = TAP_spccFilterChannel(selected);
        if (selectedChannel.length > 0 && selectedChannel != channel) {
            selected =
                channel == "R" ? "Sony Color Sensor R-UVIRcut" :
                    channel == "G" ? "Sony Color Sensor G-UVIRcut" :
                        "Sony Color Sensor B-UVIRcut";
        }
        TAP_comboSelectText(combo, selected);
        row.add(label);
        row.add(combo, 100);
        return { row: row, label: label, combo: combo };
    }
    var redFilterUI = makeFilterCombo(p3, "Red Filter:", initialSettings.spccRedFilter, "R");
    var greenFilterUI = makeFilterCombo(p3, "Green Filter:", initialSettings.spccGreenFilter, "G");
    var blueFilterUI = makeFilterCombo(p3, "Blue Filter:", initialSettings.spccBlueFilter, "B");
