    var sharpEngineRow = new HorizontalSizer;
    sharpEngineRow.spacing = 6;
    sharpEngineRow.add(this.sharpenEngine_Label);
    sharpEngineRow.add(this.sharpenEngine_Combo, 100);
    // BlurX native-style layout. The script intentionally does not expose an ML
