    this.info_Label.text =
        "AstroTemps AutoProcessing Tool was created by Felipe Temponi to concentrate astrophotography processing processes and scripts " +
            "in a single workflow and make astrophotography post-processing easier to manage. This project may be modified for " +
            "personal/non-commercial use, but it must not be sold or commercialized. Third-party components and adapted code remain " +
            "subject to their respective original licenses and notices.<br/><br/>" +
            "<b>Legacy spin-off:</b> this build targets PixInsight 1.9.3 / SpiderMonkey. Third-party modules must match the installed PixInsight version.<br/><br/>" +
            "If you would like to support the continued development of this project, I would be immensely grateful if you could buy me a coffee:";
    /*
     * Clickable support link.
     *
     * We intentionally handle the click ourselves instead of relying only on
     * Label.openExternalLinks, because some PixInsight/PJSR builds do not forward
     * rich-text anchor clicks reliably. lighthouseOpenUrl() already contains the
     * platform-specific Windows/macOS/Linux URL launcher used elsewhere by the script.
     */
    this.info_CoffeeLink = new Label(this.info_Group);
    this.info_CoffeeLink.useRichText = true;
    this.info_CoffeeLink.wordWrapping = true;
    this.info_CoffeeLink.text =
        "<b><u>www.buymeacoffee.com/temponi</u></b>";
    this.info_CoffeeLink.toolTip =
        "<p>Open https://www.buymeacoffee.com/temponi in your default browser.</p>";
    try {
        this.info_CoffeeLink.cursor = new Cursor(StdCursor_PointingHand);
    }
    catch (eCoffeeCursor) { }
    this.info_CoffeeLink.onMousePress = function (x, y, button, buttonState, modifiers) {
        if (button == MouseButton_Left)
            lighthouseOpenUrl("https://www.buymeacoffee.com/temponi");
    };
    this.info_Group.sizer = new VerticalSizer;
    this.info_Group.sizer.margin = 8;
