        dialog.dseScaling_Combo.enabled = dseActive;
        dialog.dseAmount_Control.enabled = dseActive;
        dialog.dseIterations_Label.enabled = dseActive;
        dialog.dseIterations_SpinBox.enabled = dseActive;
        dialog.updateEngineVisibility();
