    this.adbe_CheckBox.onCheck = function () { dialog.updateEnabledState(); };
    this.spcc_CheckBox.onCheck = function () { dialog.updateEnabledState(); };
    this.blurSharpen_CheckBox.onCheck = function () { dialog.updateEnabledState(); };
    this.noise_CheckBox.onCheck = function () { dialog.updateEnabledState(); };
    this.star_CheckBox.onCheck = function () { dialog.updateEnabledState(); };
