    this.run_Button = new PushButton(this);
    this.run_Button.text = "Run Processing";
    this.run_Button.defaultButton = true;
    this.close_Button = new PushButton(this);
    this.close_Button.text = "Close";
    this.validate_Button.onClick = function () {
        var s = dialog.getSettings();
        var missing = validateRequiredIcons(s);
        if (missing.length == 0) {
            (new MessageBox("All directly detectable legacy PixInsight scripts/processes for the selected steps were found. Third-party native modules must themselves be builds compatible with PixInsight 1.9.3. External SetiAstroSuitePro and GraXpert availability is verified when the corresponding stage runs.", "AstroTemps AutoProcessing Tool", StdIcon_Information, StdButton_Ok)).execute();
        }
        else {
            var message = "Scripts/processes currently not detected:\n\n";
            for (var i = 0; i < missing.length; ++i)
                message += missing[i] + "\n";
            (new MessageBox(message, "AstroTemps AutoProcessing Tool", StdIcon_Error, StdButton_Ok)).execute();
        }
    };
    this.run_Button.onClick = function () {
        if (dialog.target_ViewList.currentView.isNull) {
            (new MessageBox("Select a target image.", "AstroTemps AutoProcessing Tool", StdIcon_Error, StdButton_Ok)).execute();
            return;
        }
        var s = dialog.getSettings();
        if (!s.blurCorrect && !s.autoDBE && !s.spcc && !s.blurSharpen &&
            !s.noiseX && !s.starX && !s.findBackground && !s.narrowbandNormalization &&
            !s.statisticalStretch && !s.lighthouse &&
            !s.darkStructureEnhance && !s.starStretch && !s.screenStars) {
            (new MessageBox("No processing steps are selected.", "AstroTemps AutoProcessing Tool", StdIcon_Error, StdButton_Ok)).execute();
            return;
        }
        if (s.starStretch && s.starX) {
            if (s.starRemovalEngine == STAR_ENGINE_STARX && !s.starOutputStars) {
                (new MessageBox("Star Stretch requires StarXTerminator > Output Stars.", "AstroTemps AutoProcessing Tool", StdIcon_Error, StdButton_Ok)).execute();
                return;
            }
            if (s.starRemovalEngine == STAR_ENGINE_STARNET && !s.starnetMask) {
                (new MessageBox("Star Stretch requires StarNet2 > Mask / Output Stars.", "AstroTemps AutoProcessing Tool", StdIcon_Error, StdButton_Ok)).execute();
                return;
            }
        }
        if (s.screenStars && !s.starStretch && TAPSCREEN_findNBtoRGBStarsView() == null) {
            (new MessageBox("Blend Image + Stars requires NBtoRGB_stars. Enable Star Stretch or open an existing NBtoRGB_stars image.", "AstroTemps AutoProcessing Tool", StdIcon_Error, StdButton_Ok)).execute();
            return;
        }
        dialog.ok();
    };
    this.close_Button.onClick = function () { dialog.cancel(); };
    var actionSizer = new HorizontalSizer;
